from common import *
from report import num,delta,table
LABEL={"qwen":"Qwen, три поля","bmthree":"BM25, три поля","lrthree":"Логистическая модель, три поля","bmnine":"BM25, расширенный запрос","lrnine":"Логистическая модель, расширенный запрос",
       "qwen_seen":"Qwen, три поля + отсрочка","bmthree_seen":"BM25, три поля + отсрочка","lrthree_seen":"Логистическая модель, три поля + отсрочка","bmnine_seen":"BM25, расширенный запрос + отсрочка","lrnine_seen":"Логистическая модель, расширенный запрос + отсрочка"}
def main():
    r=read(OUT/"matched-results.json");p=r["panels"]["outside204"];seal=read(OUT/"matched-seal.json");ck=read(OUT/"matched-token-seal.json");changes=seal["different_queries"]["outside204"]
    out=["# Контроль равенства видимого текста на SERBench",
         "Qwen3-Embedding-8B и два лексических ранжировщика получили одну последовательность входа. Она составлена из инструкции, информационной потребности агента, текущей цели и описания issue. Текст каждого кандидата содержит путь и выдержку. На стороне лексических моделей все признаки вычислены после той же токенизации GGUF, по первым 511 токенам плюс EOS. Словарь и входные представления остаются равными. Логистическая модель видела train-разметку SERBench, Qwen использовалась zero-shot. [Заранее заданный протокол](MATCHED_INPUT_RU.md)",
         f"На 204 состояниях вне пилота в режиме общей отсрочки просмотренных единиц логистическая модель закрыла MSS@5 в {p['methods']['lrthree_seen']['complete_counts'][0]} случаях, BM25 — в {p['methods']['bmthree_seen']['complete_counts'][0]}, Qwen — в {p['methods']['qwen_seen']['complete_counts'][0]}. При одинаковом потолке в 2 048 токенов эти числа равны соответственно {p['methods']['lrthree_seen']['complete_counts'][2]}, {p['methods']['bmthree_seen']['complete_counts'][2]} и {p['methods']['qwen_seen']['complete_counts'][2]}.",
         table(p,LABEL,LABEL)]
    comparisons=["| Контраст на 204 | MSS@5, разность и 95%-й интервал, п.п. | MSS при 2 048, п.п. | Выигрыши / потери при MSS@5 |","|---|---|---|---:|"]
    for a,z in p["contrasts"].items():
        a,b=a.split(" minus ");comparisons.append(f"| {LABEL[a]} минус {LABEL[b]} | {delta(z)} | {delta(z,2)} | {z['wins'][0]} / {z['losses'][0]} |")
    out+=["\n".join(comparisons),f"Дополнительные поля изменили фактические токены запроса в {changes}/204 случаях. Позиция поля issue перемещается относительно точки усечения, поэтому это совокупный эффект доступной истории и распределения ограниченных входных токенов. Выбор C на 101 dev: {seal['selection']['three']['C']} для трёх полей и {seal['selection']['nine']['C']} для расширенного запроса. Обучение включало {seal['train']} состояний, из них {seal['single_class_train']} с единственным классом кандидатов. Лексические методы используют точные BPE-единицы, без стемминга и дополнительной токенизации исходных символов.",
        f"По всем 214 состояниям независимо подтверждены длины {r['exact_length_checks']} строк перед усечением, включая весь набор кандидатов Qwen. Несовпадений {r['length_mismatches']}. В данном запуске получены {ck['unique_strings']} уникальных текстов для всех 494 состояний train/dev/test, все {ck['independent_native']} строки по отдельности обработаны исходной HTTP-функцией /tokenize. Сравнение с первоначальной пакетной токенизацией выявило {ck['byte_io_disagrees']} несовпадающих входов, их исправили до оценки качества текстовых контролей. Программа токенизации работала на CPU, эмбеддинги Qwen — на RTX 3090. В архиве сохранены ранги и числовые признаки проверки; токенизированный исходный текст находится только в локальном кэше. [Поправка к обработке CRLF](TOKENIZER_NOTE_RU.md) · [Все панели](matched-results.json)",
        "Основной R39 использует дополнительные входные поля, внешние dense-представления и признаки стоимости. Для него таблица основного отчёта остаётся сравнением систем. Новые текстовые контроли характеризуют абляцию состава видимого запроса и различие обученного лексического и плотного ранжирования в этой коллекции. [Основной отчёт](REPORT_RU.md)"]
    (OUT/"MATCHED_REPORT_RU.md").write_text("\n\n".join(out)+"\n",encoding="utf8")
if __name__=="__main__":main()
